/// <summary>
/// This class holds event handler
/// </summary>
internal final class METGUPPricingAttributeFormEventHandler
{
}

Method.Source:
/// <summary>
/// Used for adding additional validation
/// </summary>
/// <param name="sender">Sender</param>
/// <param name="e">e</param>
[FormDataSourceEventHandler(formDataSourceStr(GUPPricingAttributeGroup, GUPPricingAttributeGroup), FormDataSourceEventType::ValidatingDelete),
    SuppressBpWarning('BPParameterNotUsed', 'Unused parameters cannot be deleted from event handlers.')]
public static void GUPPricingAttributeGroup_OnValidatingDelete(FormDataSource sender, FormDataSourceEventArgs e)
{
    TAMRebateGroup              rebGrp;
    FormRun                     fr                      = sender.formRun();
    GUPPricingAttributeGroup    pricingAttributeGroup   = fr.dataSource().cursor();
    
    select firstonly rebGrp 
        where   rebGrp.METGUPProductPricingAttributeGroup == pricingAttributeGroup.Name;
    if (rebGrp)
    {
        throw error("@MET:PriceAttribDel");
    }
}
